import React from 'react'
import { Input, Form, Select, DatePicker, Dropdown, Button } from 'antd'
import moment from 'moment-timezone'

export function getFormItems (formData, form) {
  const { getFieldDecorator } = form
  const {
    fieldName,
    type: Type,
    label = ' ',
    initialValue,
    disabled = false,
    isMultiple,
    required = false
  } = formData

  const { type } = Type
  switch (type) {
    case 'string': {
      const options = formData?.type?.options
      if (options && Array.isArray(options)) {
        return (
          <Form.Item
            label={<b style={{ fontSize: '12px' }}>{label}</b>}
            key={label}
            style={{ width: '100%' }}
          >
            {getFieldDecorator(fieldName, {
              initialValue: handleGetDefaultValue(initialValue, fieldName)
            })(
              <Select
                mode={isMultiple ? 'multiple' : undefined}
                showSearch
                placeholder={
                  isMultiple ? 'Select one or more' : 'Select an option'
                }
                disabled={disabled}
                className='dropdown-input'
                filterOption={(input, option) =>
                  option.props.children
                    .toLowerCase()
                    .indexOf(input.toLowerCase()) >= 0}
                style={{ width: '100%' }}
              >
                {options?.length > 0 &&
                  options.map((option, index) => {
                    return (
                      <Select.Option
                        key={index}
                        value={option.key ? option.key : option}
                      >
                        {option.value ? option.value : option}
                      </Select.Option>
                    )
                  })}
              </Select>
            )}
          </Form.Item>
        )
      }
      return (
        <Form.Item
          label={<b style={{ fontSize: '12px' }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: handleGetDefaultValue(initialValue, fieldName),
            rules: [
              {
                required: required,
                message: `Please enter ${label}`
              }
            ]
          })(<Input disabled={fieldName === 'reference_id'} />)}
        </Form.Item>
      )
    }
    case 'datetime': {
      return (
        <Form.Item
          label={<b style={{ fontSize: '12px' }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: moment(
              handleGetDefaultValue(initialValue, fieldName)
            )
          })(
            <DatePicker
              format='YYYY-MM-DD'
              disabledDate={(current) =>
                current && current < moment().startOf('day')}
            />
          )}
        </Form.Item>
      )
    }
    case 'textArea': {
      return (
        <Form.Item
          label={<b style={{ fontSize: '12px' }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: handleGetDefaultValue(initialValue, fieldName)
          })(<Input.TextArea rows={4} placeholder={`Enter ${label}`} />)}
        </Form.Item>
      )
    }
    case 'time': {
      return (
        <Form.Item
          label={<b style={{ fontSize: '12px' }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: handleGetDefaultValue(initialValue, fieldName)
          })(<Input type='time' step='1' />)}
        </Form.Item>
      )
    }
    case 'calendar': {
      const selectedValue = form.getFieldValue(fieldName)

      return (
        <Form.Item
          label={<b style={{ fontSize: '12px' }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: handleGetDefaultValue(initialValue, fieldName)
          })(
            <CalendarDropdown
              value={selectedValue}
              onChange={(val) => form.setFieldsValue({ [fieldName]: val })}
            />
          )}
        </Form.Item>
      )
    }
    case 'emailGroup': {
      return (
        <Form.Item
          label={<b style={{ fontSize: '12px' }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: [],
            rules: [
              {
                required: required,
                message: `Please enter ${label}`
              }
            ]
          })(
            <EmailGroup
              form={form}
              fieldName={fieldName}
              defaultValue={handleGetDefaultValueEmailGroup(
                initialValue,
                fieldName
              )}
            />
          )}
        </Form.Item>
      )
    }
    default:
      return null
  }
}

const SimpleCalendar = ({ value, onSelect }) => {
  const dates = Array.from({ length: 30 }, (_, i) => i + 1)

  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(7, 1fr)',
        gap: '8px',
        background: 'white'
      }}
    >
      {dates.map((date, index) => (
        <div
          onClick={() => onSelect && onSelect(date)}
          style={{
            textAlign: 'center',
            padding: '2px',
            cursor: 'pointer',
            backgroundColor: value === date ? '#e6f7ff' : '#fff'
          }}
          key={index}
        >
          {date}
        </div>
      ))}
    </div>
  )
}

const CalendarDropdown = ({ value, onChange }) => {
  const [open, setOpen] = React.useState(false)

  const handleSelect = (val) => {
    onChange(val)
    setOpen(false)
  }

  return (
    <Dropdown
      overlay={<SimpleCalendar value={value} onSelect={handleSelect} />}
      visible={open}
      onVisibleChange={setOpen}
      trigger={['click']}
    >
      <Input
        readOnly
        onClick={() => setOpen(true)}
        value={value ? `${value}` : ''}
        placeholder='Select date'
      />
    </Dropdown>
  )
}

export default SimpleCalendar

const EmailGroup = ({
  form,
  fieldName,
  defaultValue = [{ name: '', email: '' }]
}) => {
  const [emailFields, setEmailFields] = React.useState(defaultValue)

  const addEmailField = () => {
    const newFields = [...emailFields, { name: '', email: '' }]
    setEmailFields(newFields)
    form.setFieldsValue({ [fieldName]: newFields })
  }

  const handleEmailChange = (index, key, value) => {
    const updated = [...emailFields]
    updated[index][key] = value
    setEmailFields(updated)
    form.setFieldsValue({ [fieldName]: updated })
  }

  const handleDeleteField = (index) => {
    const updated = emailFields.filter((_, i) => i !== index)
    setEmailFields(updated)
    form.setFieldsValue({ [fieldName]: updated })
  }

  React.useEffect(() => {
    form.setFieldsValue({ [fieldName]: emailFields })
  }, [])

  return (
    <div>
      {emailFields.map((item, index) => (
        <div
          key={index}
          style={{
            display: 'flex',
            gap: '8px',
            marginBottom: '8px',
            alignItems: 'center'
          }}
        >
          <Input
            placeholder='Name'
            value={item.name}
            onChange={(e) => handleEmailChange(index, 'name', e.target.value)}
          />
          <Input
            placeholder='Email'
            value={item.email}
            onChange={(e) => handleEmailChange(index, 'email', e.target.value)}
          />
          <Button
            shape='circle'
            type='danger'
            icon='delete'
            onClick={() => handleDeleteField(index)}
            disabled={emailFields.length === 1}
          />
        </div>
      ))}
      <Button onClick={addEmailField} type='dashed' style={{ width: '100%' }}>
        + Add
      </Button>
    </div>
  )
}

const handleGetDefaultValue = (values, key) => {
  const item = values?.length > 0 && values.find((item) => item.key === key)
  return item ? item.value : ''
}

const handleGetDefaultValueEmailGroup = (values, key) => {
  const item =
    values?.length > 0 && values.find((item) => item.key === 'email')
  const objKey = item?.value?.[key] && Object.keys(item?.value?.[key])
  const finalData = []
  if (objKey?.length > 0) {
    objKey.forEach(keyName => {
      finalData.push({ name: item?.value?.[key]?.[keyName], email: keyName })
    })
  }
  return finalData
}
