import {
  Button,
  Col,
  Form,
  Icon,
  Row,
  Spin,
  Table,
  Modal,
  Input,
  notification
} from 'antd'
import {
  DetailTabHeader,
  DetailTabs,
  DetailTabSubHeader,
  DetailTabWrapper,
  EditBtn,
  LayoutContentStyle,
  LayoutWrapper,
  ReportConfigStyleWrapper,
  TabsHeader
} from '../index.style'
import reportingconfigActions from '../../../redux/reportingConfig/actions'
import { connect } from 'react-redux'
import { useEffect, useMemo, useState } from 'react'
import { useParams } from 'react-router-dom'
import { getFormItems } from '../helpers/formItems'
import { addFormData } from '../helpers/data'
import productconfigActions from '../../../redux/productConfig/actions'
import {
  capitalizeFirstLetter,
  formatDate,
  stringOfArrayOfStringHandler
} from '../../../../helpers/utility'

const { TextArea } = Input
const { getProductList, productDetailPackges } = productconfigActions
const {
  updateReportingConfig,
  resetReportingConfigRedux,
  getReportLogs,
  updateReportLogs,
  getUpdateLogs
} = reportingconfigActions

const ReportingConfigDetail = ({
  getReportingConfigDetails,
  reportingDetailsLoading,
  reportingConfigDetails,
  ...props
}) => {
  const {
    getProductList,
    productList,
    productDetailPackges,
    productDetailPackagesData,
    productListLoading = false,
    productDetailPackagesLoading = false,
    updateReportingConfig,
    updateReportingConfigMessage,
    resetReportingConfigRedux,
    getReportLogs,
    reportLogsData,
    reportLogsLoading,
    updateReportLogsData,
    updateReportLogsMessage,
    updateReportLogs,
    getUpdateLogs,
    updateLogsData,
    updateLogsLoading
  } = props
  const { id } = useParams()
  const [configDetails, setConfigDetails] = useState({})
  const [isEdit, setIsEdit] = useState({
    reportDistribution: true,
    reportTemplate: true,
    reportQuery: true
  })
  const [product, setproducts] = useState([])
  const [pkg, setPkg] = useState([])
  const [descriptionData, setDescriptionData] = useState([
    { sql: '', isEdit: false }
  ])
  const [reportLogsQuery, setReportLogsQuery] = useState({})
  const [updateLogsQuery, setUpdateLogsQuery] = useState({})

  useEffect(() => {
    getReportingConfigDetails({ id })
    getProductList({ query: {} })
  }, [])

  useEffect(() => {
    if (
      updateReportingConfigMessage &&
      updateReportingConfigMessage === 'success'
    ) {
      notification.success({ message: 'Config Updated Succesfully!' })
      resetReportingConfigRedux(['updateReportingConfigMessage'])
      getReportingConfigDetails({ id })
    }
  }, [updateReportingConfigMessage])

  useEffect(() => {
    if (productList?.data?.details) {
      const transformed = productList?.data?.details?.map((item) => ({
        key: item.code,
        value: item.name
      }))
      setproducts(transformed)
    }
  }, [productList])

  useEffect(() => {
    if (productDetailPackagesData?.data?.details) {
      const transformed = productDetailPackagesData?.data?.details?.map(
        (item) => ({
          key: item.code,
          value: item.name
        })
      )
      setPkg(transformed)
    }
  }, [productDetailPackagesData])

  useEffect(() => {
    if (reportLogsQuery?.dag_id) {
      getReportLogs({
        query: reportLogsQuery
      })
    }
  }, [reportLogsQuery])

  useEffect(() => {
    if (updateLogsQuery?.report_id) {
      getUpdateLogs({
        query: {
          page_size: updateLogsQuery.page_size,
          page: updateLogsQuery.page
        },
        id: updateLogsQuery.report_id
      })
    }
  }, [updateLogsQuery])

  useEffect(() => {
    if (props.form.getFieldValue('product_key')) {
      setPkg([])
      productDetailPackges({
        query: { productCode: props.form.getFieldValue('product_key') }
      })
    }
  }, [props.form.getFieldValue('product_key')])

  useEffect(() => {
    if (
      reportingConfigDetails?.results &&
      reportingConfigDetails.results.length
    ) {
      setConfigDetails(reportingConfigDetails.results[0])
      setDescriptionData([
        { sql: reportingConfigDetails.results[0]?.sql, isEdit: false }
      ])
      setReportLogsQuery({
        // dag_id: 'aus_daily_member_report_sftp',
        dag_id: reportingConfigDetails.results[0]?.dag_id,
        offset: 0,
        limit: 10
      })
      setUpdateLogsQuery({
        report_id: reportingConfigDetails.results[0]?.id,
        page: 1,
        page_size: 10
      })
    }
  }, [reportingConfigDetails])

  useEffect(() => {
    if (updateReportLogsMessage && updateReportLogsMessage === 'success') {
      notification.success({
        message:
          updateReportLogsData?.message ?? 'DAG Retriggered successfully'
      })
      getReportLogs({ query: reportLogsQuery })
    } else if (updateReportLogsMessage && updateReportLogsMessage === 'error') {
      notification.error({
        message: 'Something Wrong when Retriggering DAG'
      })
    }
  }, [updateReportLogsMessage])

  const handleOnBackGocarData = () => {
    const { history } = props
    history.push('/reporting-config')
  }

  const value1 = useMemo(() => {
    const baseValues = [
      {
        key: '1',
        name: <strong>Report Name</strong>,
        value: configDetails.report_name || '-'
      },
      {
        key: '2',
        name: <strong>Reporting Type</strong>,
        value: configDetails.report_type || '-'
      },
      {
        key: '3',
        name: <strong>Via</strong>,
        value: configDetails.report_via || '-'
      },
      {
        key: '4',
        name: <strong>For</strong>,
        value: configDetails.channel || '-'
      },
      {
        key: '5',
        name: <strong>Target</strong>,
        value: configDetails.report_via || '-'
      }
    ]
    if (configDetails.report_via === 'EMAIL') {
      baseValues.push({
        key: '6',
        name: <strong>Subject Line</strong>,
        value: configDetails.extra_data?.subject_line || '-'
      })
    }

    return baseValues
  }, [configDetails])

  const value2 = useMemo(() => {
    const {
      recipients_internal: recipientsInternal = {},
      recipients_external: recipientsExternal = {}
    } = configDetails
    return [
      {
        key: 'email',
        name: <strong>Email Recipients</strong>,
        value:
          {
            recipients_internal: recipientsInternal,
            recipients_external: recipientsExternal
          } || {}
      },
      {
        key: 'trigger_frequency',
        name: <strong>Triggered in</strong>,
        value: configDetails.trigger_frequency || '-'
      },
      {
        key: 'trigger_period',
        name: <strong>Basis Every</strong>,
        value: configDetails.trigger_period || '-'
      },
      {
        key: 'trigger_time',
        name: <strong>On</strong>,
        value: `${configDetails.trigger_time} UTC` || '-',
        style: { width: '100%' }
      },
      {
        key: 'start_date',
        name: <strong>Start From</strong>,
        value: configDetails.start_date || '-'
      }
    ]
  }, [configDetails])

  const value3 = useMemo(() => {
    return [
      {
        key: 'product_key',
        name: <strong>Product</strong>,
        value: configDetails?.extra_data?.product_key || '-'
      },
      {
        key: 'package_name',
        name: <strong>Packages</strong>,
        value: configDetails?.extra_data?.package_name || '-'
      },
      {
        key: 'state',
        name: <strong>With State</strong>,
        value: configDetails.state || '-'
      },
      {
        key: 'output_format',
        name: <strong>File Type</strong>,
        value: configDetails.output_format || '-'
      }
    ]
  }, [configDetails])

  const updateLogsColumns = [
    {
      key: 'no',
      title: 'No',
      render: (_, record, index) => <p>{updateLogsQuery?.page + index}</p>
    },
    {
      key: 'updated_at',
      title: 'Updated On',
      render: (_, record) => (
        <p>{formatDate(record.updated_at, 'YYYY-MM-DD HH:mm:ss')}</p>
      )
    },
    {
      key: 'attributes',
      title: 'Attributes',
      render: (_, record) => <p>{capitalizeFirstLetter(record.attributes)}</p>
    },
    {
      key: 'changes_from',
      title: 'Changes From',
      render: (_, record) => (
        <p>{stringOfArrayOfStringHandler(record.changes_from)}</p>
      )
    },
    {
      key: 'changes_to',
      title: 'Changes Into',
      render: (_, record) => (
        <p>{stringOfArrayOfStringHandler(record.changes_to)}</p>
      )
    },
    {
      key: 'changed_by',
      title: 'Changed By',
      dataIndex: 'changed_by'
    }
  ]

  const reportLogsColumns = [
    {
      key: 'no',
      title: 'No',
      render: (_, record, index) => (
        <p>{(reportLogsQuery?.offset ?? 0) + index + 1}</p>
      )
    },
    {
      key: 'execution_date',
      title: 'Sent At',
      dataIndex: 'execution_date'
    },
    {
      key: 'state',
      title: 'Status',
      dataIndex: 'state'
    },
    {
      key: 'actions',
      title: 'Actions',
      render: (_, record) => (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <Button
            style={{ color: '#0096FA', fontWeight: '800' }}
            type='link'
            onClick={() => handleResend(record?.dag_id)}
          >
            Resend
          </Button>
        </div>
      )
    }
  ]

  const reportTemplateColumns = [
    {
      title: 'SQL Query',
      dataIndex: 'sql',
      key: 'sql',
      render: (text, record) => (
        <TextArea
          value={record.sql}
          rows={4}
          onChange={handleTextChange}
          placeholder='Enter description...'
          disabled={!record.isEdit}
        />
      )
    },
    {
      key: 'actions',
      title: 'Actions',
      render: (_, record) => (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <Button
            style={{ color: '#0096FA', fontWeight: '800' }}
            type='link'
            onClick={() => console.log('View', record)}
          >
            View
          </Button>
          <Button
            style={{ color: '#00B432', fontWeight: '800' }}
            type='link'
            onClick={() =>
              handleEditChange('reportTemplate', !isEdit.reportTemplate)}
          >
            {isEdit?.reportTemplate ? 'Edit' : 'Save'}
          </Button>
          <Button
            style={{ color: '#FA3232', fontWeight: '800' }}
            type='link'
            danger
            onClick={() => console.log('Delete', record)}
          >
            Delete
          </Button>
        </div>
      )
    }
  ]

  const handleResend = (dagId) => {
    updateReportLogs({ dag_id: dagId })
  }

  const handleTextChange = (e) => {
    setDescriptionData([{ ...descriptionData[0], sql: e.target.value }])
  }

  const handleEditChange = (id, isSave) => {
    if (isSave) handleConfirmEdit(id)
    else {
      setIsEdit({ ...isEdit, [id]: !isEdit[id] })
      if (id === 'reportTemplate') {
        setDescriptionData([{ ...descriptionData[0], isEdit: true }])
      }
    }
  }

  const handleConfirmEdit = (id) => {
    Modal.confirm({
      title: <p>Are you sure want to make the changes?</p>,
      okText: 'OK',
      cancelText: 'Cancel',
      onOk: () => handleUpdate(id)
    })
  }

  const handleReportLogsPagination = (val) => {
    setReportLogsQuery({
      ...reportLogsQuery,
      offset: (reportLogsQuery?.limit ?? 10) * (val?.current - 1)
    })
  }
  const handleUpdateLogsPagination = (val) => {
    setUpdateLogsQuery({
      ...updateLogsQuery,
      page: val.current ?? 1
    })
  }

  const handleUpdate = (id) => {
    props.form.validateFields((err, values) => {
      if (err) return
      const emailInternal = {}
      const emailExternal = {};

      (values.recipients_internal || []).forEach((item) => {
        if (item.email && item.name) {
          emailInternal[item.email] = item.name
        }
      });

      (values.recipients_external || []).forEach((item) => {
        if (item.email && item.name) {
          emailExternal[item.email] = item.name
        }
      })
      const updated = { ...values }
      if (
        emailInternal !== undefined &&
        Object.keys(emailInternal)?.length > 0
      ) {
        updated.recipients_internal = emailInternal
      }
      if (
        emailExternal !== undefined &&
        Object.keys(emailExternal)?.length > 0
      ) {
        updated.recipients_external = emailExternal
      }

      if (values.start_date) {
        updated.start_date = formatDate(values.start_date, 'YYYY-MM-DD')
      }
      const extraData = {}
      const { extra_data: originalExtraData = {} } = configDetails

      if ('product_key' in updated) {
        const updatedVal = updated.product_key
        const originalVal = originalExtraData.product_key
        if (JSON.stringify(updatedVal) !== JSON.stringify(originalVal)) {
          extraData.product_key = updatedVal
        } else delete updated.product_key
      }

      if ('package_name' in updated) {
        const updatedVal = updated.package_name
        const originalVal = originalExtraData.package_name
        if (JSON.stringify(updatedVal) !== JSON.stringify(originalVal)) {
          extraData.package_name = updatedVal
        } else delete updated.package_name
      }

      if (configDetails.report_via === 'EMAIL' && 'subject_line' in updated) {
        if (updated.subject_line !== originalExtraData.subject_line) {
          extraData.subject_line = updated.subject_line
        }
        delete updated.subject_line
      }
      delete updated.trigger_period
      const payload = { report_id: configDetails.id }

      Object.keys(updated).forEach((key) => {
        switch (key) {
          case 'recipients_internal':
          case 'recipients_external': {
            const prev = configDetails[key] || {}
            const curr = updated[key]
            const currKeys = Object.keys(curr)
            const prevKeys = Object.keys(prev)

            if (currKeys.length !== prevKeys.length) {
              payload[key] = curr
            } else {
              const isSame = currKeys.every((k) => curr[k] === prev[k])
              if (!isSame) payload[key] = curr
            }
            break
          }

          case 'start_date': {
            const prevDate = formatDate(configDetails.start_date, 'YYYY-MM-DD')
            const currDate = updated.start_date
            if (currDate !== prevDate) {
              payload.start_date = currDate
            }
            break
          }

          default: {
            if (updated[key] !== configDetails[key]) {
              payload[key] = updated[key]
            }
          }
        }
      })
      if (
        descriptionData[0]?.sql &&
        descriptionData[0].sql !== configDetails.sql
      ) {
        payload.sql = descriptionData[0].sql
      }
      if (Object.keys(payload).length > 0) {
        updateReportingConfig(payload)
      }
      setIsEdit({ ...isEdit, [id]: !isEdit[id] })
      if (id === 'reportTemplate') {
        setDescriptionData([{ ...descriptionData[0], isEdit: false }])
      }
    })
  }

  return (
    <LayoutWrapper>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          cursor: 'pointer',
          fontWeight: '800',
          marginBottom: '32px',
          marginTop: '16px'
        }}
        onClick={handleOnBackGocarData}
      >
        <Icon type='left' style={{ fontSize: '24px', marginRight: 8 }} />
        <div style={{ fontSize: '24px', fontWeight: '800' }}>Report Detail</div>
      </div>
      <Form hideRequiredMark>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <Spin tip='Loading ...' spinning={reportingDetailsLoading}>
              <Row type='flex'>
                <Col>
                  <TabsHeader>General Details</TabsHeader>
                </Col>
              </Row>
              <div>
                <Row>
                  <Col>
                    <DetailTabWrapper>
                      {value1?.length > 0 &&
                        value1.map((data, index) => {
                          return (
                            <DetailTabs key={index}>
                              <DetailTabHeader>{data.name}</DetailTabHeader>
                              <DetailTabSubHeader>
                                {data.value}
                              </DetailTabSubHeader>
                            </DetailTabs>
                          )
                        })}
                    </DetailTabWrapper>
                  </Col>
                </Row>
              </div>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <Spin tip='Loading ...' spinning={reportingDetailsLoading}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  width: '100%'
                }}
              >
                <TabsHeader>Report Distribution</TabsHeader>
                <EditBtn
                  isEdit={isEdit.reportDistribution}
                  onClick={() =>
                    handleEditChange(
                      'reportDistribution',
                      !isEdit.reportDistribution
                    )}
                >
                  {isEdit.reportDistribution ? 'Edit' : 'Save'}
                </EditBtn>
              </div>
              <div style={{ width: '100%' }}>
                {!isEdit.reportDistribution
                  ? (
                    <DetailTabWrapper>
                      {Object.keys(addFormData.report_distribution).map(
                        (item) => {
                          if (
                            addFormData.report_distribution[item] &&
                          item === 'trigger_period'
                          ) {
                            const triggerFrequency =
                            props.form.getFieldValue('trigger_frequency')
                            if (triggerFrequency === 'Daily') return null
                            if (triggerFrequency === 'monthly') {
                              return getFormItems(
                                {
                                  fieldName: item,
                                  type: {
                                    ...addFormData.report_distribution[item],
                                    type: 'calendar'
                                  },
                                  label: capitalizeFirstLetter(
                                    addFormData.report_distribution[item]
                                      .field_name
                                  ),
                                  initialValue: value2,
                                  required: true
                                },
                                props.form
                              )
                            }
                            return getFormItems(
                              {
                                fieldName: item,
                                type: addFormData.report_distribution[item],
                                label: capitalizeFirstLetter(
                                  addFormData.report_distribution[item].field_name
                                ),
                                initialValue: value2,
                                required: true
                              },
                              props.form
                            )
                          }
                          if (addFormData.report_distribution[item]) {
                            return getFormItems(
                              {
                                fieldName: item,
                                type: addFormData.report_distribution[item],
                                label: capitalizeFirstLetter(
                                  addFormData.report_distribution[item].field_name
                                ),
                                initialValue: value2,
                                required: true
                              },
                              props.form
                            )
                          }
                          return null
                        }
                      )}
                    </DetailTabWrapper>
                    )
                  : (
                    <DetailTabWrapper>
                      {value2?.length > 0 &&
                      value2.map((data, index) => {
                        let val = data?.value
                        if (data?.key === 'email') {
                          const internalEmails = Object.keys(
                            data?.value?.recipients_internal ?? {}
                          )
                          const externalEmails = Object.keys(
                            data?.value?.recipients_external ?? {}
                          )
                          val = [...internalEmails, ...externalEmails].join(
                            ', '
                          )
                        }
                        return (
                          <DetailTabs key={index}>
                            <DetailTabHeader>{data.name}</DetailTabHeader>
                            <DetailTabSubHeader>{val}</DetailTabSubHeader>
                          </DetailTabs>
                        )
                      })}
                    </DetailTabWrapper>
                    )}
              </div>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <Spin tip='Loading ...' spinning={reportingDetailsLoading}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  width: '100%'
                }}
              >
                <TabsHeader>Report Template</TabsHeader>
              </div>
              <div className='table-container'>
                <Table
                  bordered
                  columns={reportTemplateColumns}
                  dataSource={descriptionData}
                  rowKey={(record, index) => index}
                  pagination={false}
                />
              </div>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <Spin
              tip='Loading ...'
              spinning={
                reportingDetailsLoading ||
                productListLoading ||
                productDetailPackagesLoading
              }
            >
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  width: '100%'
                }}
              >
                <TabsHeader>Report Query</TabsHeader>
                <EditBtn
                  isEdit={isEdit.reportQuery}
                  onClick={() =>
                    handleEditChange('reportQuery', !isEdit.reportQuery)}
                >
                  {isEdit.reportQuery ? 'Edit' : 'Save'}
                </EditBtn>
              </div>
              <div>
                {!isEdit.reportQuery
                  ? (
                    <DetailTabWrapper>
                      {Object.keys(addFormData.report_query).map((item) => {
                        if (
                          addFormData.report_query[item] &&
                        item === 'product_key'
                        ) {
                          return getFormItems(
                            {
                              fieldName: item,
                              type: {
                                ...addFormData.report_query[item],
                                options: product
                              },
                              label: capitalizeFirstLetter(item),
                              initialValue: value3,
                              required: true,
                              isMultiple: true
                            },
                            props.form
                          )
                        }
                        if (
                          addFormData.report_query[item] &&
                        item === 'package_name'
                        ) {
                          const isProductSelected =
                          !!props.form.getFieldValue('product_key') &&
                          pkg.length
                          return getFormItems(
                            {
                              fieldName: item,
                              type: {
                                ...addFormData.report_query[item],
                                options: pkg
                              },
                              disabled: !isProductSelected,
                              label: capitalizeFirstLetter(item),
                              initialValue: value3,
                              required: true,
                              isMultiple: true
                            },
                            props.form
                          )
                        }
                        if (addFormData.report_query[item]) {
                          return getFormItems(
                            {
                              fieldName: item,
                              type: addFormData.report_query[item],
                              label: capitalizeFirstLetter(item),
                              initialValue: value3,
                              required: true
                            },
                            props.form
                          )
                        }
                        return null
                      })}
                    </DetailTabWrapper>
                    )
                  : (
                    <DetailTabWrapper>
                      {value3?.length > 0 &&
                      value3.map((data, index) => {
                        return (
                          <DetailTabs key={index}>
                            <DetailTabHeader>{data.name}</DetailTabHeader>
                            <DetailTabSubHeader>
                              {data.value}
                            </DetailTabSubHeader>
                          </DetailTabs>
                        )
                      })}
                    </DetailTabWrapper>
                    )}
              </div>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <Spin tip='Loading ...' spinning={reportingDetailsLoading}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  width: '100%'
                }}
              >
                <TabsHeader>Update Logs</TabsHeader>
              </div>
              <div className='table-container'>
                <Spin
                  spinning={updateLogsLoading}
                  tip='Update Logs Loading ...'
                >
                  <Table
                    bordered
                    columns={updateLogsColumns}
                    dataSource={updateLogsData?.results ?? []}
                    rowKey={(record) => record.id}
                    pagination={{
                      pageSize: updateLogsQuery?.page_size,
                      defaultCurrent: 1,
                      total: updateLogsData?.count ?? 0
                    }}
                    onChange={handleUpdateLogsPagination}
                  />
                </Spin>
              </div>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>

        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <Spin tip='Loading ...' spinning={reportingDetailsLoading}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  width: '100%'
                }}
              >
                <TabsHeader>Report Logs</TabsHeader>
              </div>
              <div className='table-container'>
                <Spin
                  spinning={reportLogsLoading}
                  tip='Reporting Logs Loading ...'
                >
                  <Table
                    bordered
                    columns={reportLogsColumns}
                    dataSource={reportLogsData?.dag_runs ?? []}
                    rowKey={(record) => record.dag_id}
                    pagination={{
                      pageSize: reportLogsQuery?.limit ?? 10,
                      defaultCurrent: 1,
                      total: reportLogsData?.total_entries ?? 0
                    }}
                    onChange={handleReportLogsPagination}
                  />
                </Spin>
              </div>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>
      </Form>
    </LayoutWrapper>
  )
}

